{
  "name": "range-to-regex",
  "version": "1.0.0",
  "description": "Convert a numeric range like '1-100' into a single regular expression that matches any number in that range.",
  "main": "index.js",
  "bin": {
    "range-to-regex": "index.js"
  },
  "scripts": {
    "start": "node index.js",
    "test": "node test.js"
  },
  "keywords": [
    "regex",
    "regexp",
    "range",
    "number"
  ],
  "license": "MIT",
  "dependencies": {
    "to-regex-range": "^5.0.1"
  }
}

#!/usr/bin/env node
'use strict';

const toRegexRange = require('to-regex-range');

/**
 * Convert a numeric range string like "1-100" into a single RegExp
 * that matches any number within that (inclusive) range.
 *
 * @param {string} range  Range in "<min>-<max>" form, e.g. "1-100".
 * @param {object} [options]  Options forwarded to to-regex-range.
 * @returns {RegExp}
 */
function rangeToRegex(range, options) {
  if (typeof range !== 'string') {
    throw new TypeError('Expected a string range like "1-100"');
  }

  const match = /^\s*(-?\d+)\s*-\s*(-?\d+)\s*$/.exec(range);
  if (!match) {
    throw new Error(`Invalid range: "${range}" (expected "<min>-<max>")`);
  }

  const [, min, max] = match;
  const source = toRegexRange(min, max, options);
  return new RegExp(`^(?:${source})$`);
}

module.exports = rangeToRegex;

if (require.main === module) {
  const arg = process.argv[2];
  if (!arg) {
    console.error('Usage: range-to-regex <min>-<max>');
    process.exit(1);
  }

  try {
    console.log(rangeToRegex(arg).source);
  } catch (err) {
    console.error(err.message);
    process.exit(1);
  }
}

'use strict';

const assert = require('node:assert');
const rangeToRegex = require('./index.js');

const regex = rangeToRegex('1-100');

for (let n = 1; n <= 100; n++) {
  assert.ok(regex.test(String(n)), `expected ${n} to match`);
}

for (const n of ['0', '101', '-1', '1000', 'abc', '1.5']) {
  assert.ok(!regex.test(n), `expected ${n} not to match`);
}

assert.strictEqual(rangeToRegex('15-95').source, '^(?:(?:1[5-9]|[2-8][0-9]|9[0-5]))$');
assert.ok(rangeToRegex('-5-5').test('-3'));
assert.ok(!rangeToRegex('-5-5').test('6'));

assert.throws(() => rangeToRegex('nope'), /Invalid range/);
assert.throws(() => rangeToRegex(42), /Expected a string/);

console.log('All tests passed');

